-- First-login tour and "What's new" tracking (also in upgrade-onboarding.sql).
alter table public.profiles add column if not exists intro_seen boolean not null default false;
alter table public.profiles add column if not exists updates_seen int not null default 0;

-- ======== from supabase/admin.sql ========

-- Peakhill NHL Survivor: commissioner access.
-- Run in Supabase → SQL Editor. Safe to re-run.

-- Who is a commissioner. No API policies: rows can only be added here, in the SQL editor.
create table if not exists public.admins (
  user_id uuid primary key references public.profiles(id) on delete cascade
);
alter table public.admins enable row level security;

create or replace function public.is_admin() returns boolean
  language sql stable security definer set search_path = public
  as $$ select exists (select 1 from admins where user_id = auth.uid()) $$;

-- Members with email and last sign-in. Empty for anyone who isn't a commissioner.
create or replace function public.admin_members()
  returns table (user_id uuid, display_name text, email text, joined_at timestamptz, last_sign_in_at timestamptz)
  language sql stable security definer set search_path = public
  as $$
    select p.id, p.display_name, u.email::text, p.created_at, u.last_sign_in_at
    from profiles p join auth.users u on u.id = p.id
    where public.is_admin()
    order by p.created_at
  $$;

-- Who has picked for a week, and how many slots. Counts only, never the players,
-- so the commissioner gets no edge before the lock.
create or replace function public.admin_pick_status(w int)
  returns table (user_id uuid, slots int, backups int, last_saved timestamptz)
  language sql stable security definer set search_path = public
  as $$
    select pk.user_id, (count(*) filter (where pk.slot <> 'FIGHT'))::int, count(pk.alt_id)::int, max(pk.updated_at)
    from picks pk
    where pk.week = w and public.is_admin()
    group by pk.user_id
  $$;

revoke execute on function public.admin_members() from public, anon;
revoke execute on function public.admin_pick_status(int) from public, anon;
grant execute on function public.admin_members() to authenticated;
grant execute on function public.admin_pick_status(int) to authenticated;

-- ---- Removing members ----

-- Emails that can't sign up again. Only reachable through the functions below.
create table if not exists public.blocked_emails (
  email text primary key,
  blocked_at timestamptz not null default now()
);
alter table public.blocked_emails enable row level security;

-- Deletes the account and everything tied to it (profile, picks, jokers), and
-- optionally blocks the email. Commissioners can't remove themselves or each other.
create or replace function public.admin_remove_member(target uuid, block boolean default true)
  returns void
  language plpgsql security definer set search_path = public
  as $$
  declare target_email text;
  begin
    if not public.is_admin() then raise exception 'Only the commissioner can remove members.'; end if;
    if target = auth.uid() then raise exception 'You can''t remove yourself.'; end if;
    if exists (select 1 from public.admins a where a.user_id = target) then
      raise exception 'That member is a commissioner. Remove them from the admins table first.';
    end if;
    select u.email into target_email from auth.users u where u.id = target;
    if block and target_email is not null then
      insert into public.blocked_emails (email) values (lower(target_email)) on conflict do nothing;
    end if;
    delete from auth.users u where u.id = target;
  end
  $$;

create or replace function public.admin_blocked()
  returns table (email text, blocked_at timestamptz)
  language sql stable security definer set search_path = public
  as $$ select b.email, b.blocked_at from blocked_emails b where public.is_admin() order by b.blocked_at desc $$;

create or replace function public.admin_unblock(target_email text)
  returns void
  language plpgsql security definer set search_path = public
  as $$
  begin
    if not public.is_admin() then raise exception 'Only the commissioner can do that.'; end if;
    delete from public.blocked_emails b where b.email = lower(target_email);
  end
  $$;

-- Sign-ups from blocked emails fail.
create or replace function public.reject_blocked_signup()
  returns trigger
  language plpgsql security definer set search_path = public
  as $$
  begin
    if exists (select 1 from public.blocked_emails b where b.email = lower(new.email)) then
      raise exception 'This email has been removed from the league.';
    end if;
    return new;
  end
  $$;
drop trigger if exists reject_blocked_signup on auth.users;
create trigger reject_blocked_signup before insert on auth.users
  for each row execute function public.reject_blocked_signup();

revoke execute on function public.admin_remove_member(uuid, boolean) from public, anon;
revoke execute on function public.admin_blocked() from public, anon;
revoke execute on function public.admin_unblock(text) from public, anon;
grant execute on function public.admin_remove_member(uuid, boolean) to authenticated;
grant execute on function public.admin_blocked() to authenticated;
grant execute on function public.admin_unblock(text) to authenticated;

-- ======== from supabase/upgrade-dub-invite.sql ========

-- Peakhill NHL Survivor: Dub slot + invite code. Run once in the SQL editor. Safe to re-run.

-- ---- Dub: a fourth pick slot (a team's wins) ----
alter table public.picks drop constraint if exists picks_slot_check;
alter table public.picks add constraint picks_slot_check check (slot in ('PTS', 'PM', 'SV', 'WIN', 'FIGHT'));
alter table public.unburns drop constraint if exists unburns_slot_check;
alter table public.unburns add constraint unburns_slot_check check (slot in ('PTS', 'PM', 'SV', 'WIN'));

-- ---- Invite code ----
-- One settings row. No API policies: read and changed only through the functions below.
create table if not exists public.league_settings (
  id boolean primary key default true check (id),
  invite_code text
);
insert into public.league_settings (id) values (true) on conflict do nothing;
alter table public.league_settings enable row level security;

-- Starts with a random 6-character code; change it from the Commissioner tab.
update public.league_settings set invite_code = upper(substr(md5(random()::text), 1, 6))
  where id and invite_code is null;

-- True when the code matches, or when no code is set.
create or replace function public.check_invite(code text) returns boolean
  language sql stable security definer set search_path = public
  as $$
    select coalesce(
      (select s.invite_code is null or lower(s.invite_code) = lower(trim(coalesce(code, '')))
       from league_settings s where s.id),
      true)
  $$;

-- Sign-ups must carry the code (the app sends it as user metadata).
create or replace function public.require_invite() returns trigger
  language plpgsql security definer set search_path = public
  as $$
  begin
    if not public.check_invite(new.raw_user_meta_data->>'invite_code') then
      raise exception 'Invalid invite code.';
    end if;
    return new;
  end
  $$;
drop trigger if exists require_invite on auth.users;
create trigger require_invite before insert on auth.users
  for each row execute function public.require_invite();

create or replace function public.admin_get_invite() returns text
  language sql stable security definer set search_path = public
  as $$ select s.invite_code from league_settings s where s.id and public.is_admin() $$;

-- An empty code turns the requirement off.
create or replace function public.admin_set_invite(code text) returns void
  language plpgsql security definer set search_path = public
  as $$
  begin
    if not public.is_admin() then raise exception 'Only the commissioner can change the invite code.'; end if;
    update public.league_settings set invite_code = nullif(trim(code), '') where id;
  end
  $$;

-- Only the sign-up trigger calls it, so the code can't be guessed over the API.
revoke execute on function public.check_invite(text) from public, anon, authenticated;
revoke execute on function public.admin_get_invite() from public, anon;
revoke execute on function public.admin_set_invite(text) from public, anon;
grant execute on function public.admin_get_invite() to authenticated;
grant execute on function public.admin_set_invite(text) to authenticated;

-- ======== from supabase/upgrade-onboarding.sql ========

-- Peakhill NHL Survivor: remember who has seen the tour and which updates they've read.
-- Run once in the SQL editor. Safe to re-run.
alter table public.profiles add column if not exists intro_seen boolean not null default false;
alter table public.profiles add column if not exists updates_seen int not null default 0;

-- ======== from supabase/upgrade-cards.sql ========

-- Peakhill NHL Survivor: Joker cards. Run once in the Supabase SQL editor. Safe to re-run.
--
-- What's stored: the card you kept from each pack ('_keep'; in Week 1 also one 'repick:' change of mind), duel answers ('_reply'),
-- gifts and plays. The league engine rebuilds every hand from these rows and ignores
-- (and flags at the reveal) any play for a card you don't actually hold.
-- Packs are dealt from a secret seed, so nobody can work out a colleague's hand early.

create extension if not exists pgcrypto with schema extensions;

create table if not exists public.card_plays (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  week int not null references public.weeks(week),
  card text not null check (card in (
    '_keep', '_reply', 'gift',
    'jinx', 'load', 'heist', 'blue_shell', 'burn_notice', 'clown', 'nickname', 'charge', 'reverse',
    'sixth', 'copycat', 'leech', 'switcheroo', 'garbage', 'embargo', 'scout', 'duel')),
  card_uid text,
  target_id uuid references public.profiles(id) on delete cascade,
  slot text,
  player_id int,
  params jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
alter table public.card_plays drop constraint if exists card_plays_slot_check;
alter table public.card_plays add constraint card_plays_slot_check check (slot in ('PTS', 'PM', 'SV', 'WIN'));
-- Each card (or pack, for '_keep') can be used once.
create unique index if not exists card_plays_once on public.card_plays (user_id, card_uid) where card_uid is not null;
create index if not exists card_plays_week on public.card_plays (week);

-- The server sets the id and time, so nobody can backdate a play.
create or replace function public.card_plays_stamp() returns trigger
  language plpgsql as $$
  begin
    new.id := gen_random_uuid();
    new.created_at := now();
    return new;
  end
  $$;
drop trigger if exists card_plays_stamp on public.card_plays;
create trigger card_plays_stamp before insert on public.card_plays
  for each row execute function public.card_plays_stamp();

-- When a row can be added or taken back. Hindsight cards rewrite last week, so
-- they go in after that week locks and before the next one does. An Embargo
-- has to give everyone a day's notice.
create or replace function public.card_window(c text, w int) returns boolean
  language sql stable security definer set search_path = public
  as $$
    select case
      when c in ('switcheroo', 'garbage') then public.week_locked(w) and public.week_open(w + 1)
      when c = 'embargo' then exists (select 1 from weeks where week = w and lock_at > now() + interval '24 hours')
      else public.week_open(w)
    end
  $$;

alter table public.card_plays enable row level security;
drop policy if exists "card plays readable" on public.card_plays;
drop policy if exists "card plays insert own" on public.card_plays;
drop policy if exists "card plays delete own" on public.card_plays;
-- Your own rows any time; everyone's once the week locks. An Embargo is public
-- straight away, and a duel (and its answer) is visible to the other person.
create policy "card plays readable" on public.card_plays for select to authenticated
  using (
    user_id = auth.uid() or public.week_locked(week) or card = 'embargo'
    or (card in ('duel', '_reply') and target_id = auth.uid())
  );
-- Kept cards are final. (Week 1 allowed one change of mind per pack, a second '_keep' row
-- 'repick:<pack key>'; those rows still count, but no new ones are accepted.)
create policy "card plays insert own" on public.card_plays for insert to authenticated
  with check (
    user_id = auth.uid() and public.card_window(card, week)
    and (card <> '_keep' or coalesce(card_uid, '') not like 'repick:%')
  );
-- Kept cards are final, and a Scout Report can't be taken back once it's been read:
-- a made-up Scout play stays on the record and is flagged at the reveal.
create policy "card plays delete own" on public.card_plays for delete to authenticated
  using (user_id = auth.uid() and card not in ('_keep', 'scout') and public.card_window(card, week));

-- Scout Report: the five most-picked players in one slot of the open week, as
-- counts only. Answers only someone who has played a Scout Report on that slot.
create or replace function public.scout_report(w int, s text)
  returns table (player_id int, picks int, entries int)
  language sql stable security definer set search_path = public
  as $$
    select p.player_id, count(*)::int,
      (select count(distinct x.user_id)::int from picks x where x.week = w)
    from picks p
    where p.week = w and p.slot = s and public.week_open(w)
      and exists (select 1 from card_plays c where c.user_id = auth.uid() and c.week = w and c.card = 'scout' and c.slot = s)
    group by p.player_id
    order by count(*) desc, p.player_id
    limit 5
  $$;
revoke execute on function public.scout_report(int, text) from public, anon;
grant execute on function public.scout_report(int, text) to authenticated;

-- ---- Secret pack seeds ----
-- One random secret, readable by nobody through the API.
create table if not exists public.league_secret (
  id boolean primary key default true check (id),
  secret text not null
);
alter table public.league_secret enable row level security;
insert into public.league_secret (id, secret)
  values (true, encode(extensions.gen_random_bytes(32), 'hex'))
  on conflict (id) do nothing;

-- Pack seeds per person and week: your own up to the open week, everyone's once
-- a week has locked, and all of them for the hourly data job (service role).
create or replace function public.pack_seeds()
  returns table (user_id uuid, week int, seed text)
  language sql stable security definer set search_path = public, extensions
  as $$
    select p.id, w.week,
      encode(extensions.hmac(p.id::text || '|' || w.week::text, (select secret from league_secret where id), 'sha256'), 'hex')
    from profiles p cross join weeks w
    where w.lock_at <= now()
      or (p.id = auth.uid() and w.week <= coalesce((select min(x.week) from weeks x where x.lock_at > now()), w.week))
      or coalesce(auth.jwt() ->> 'role', '') = 'service_role'
  $$;
revoke execute on function public.pack_seeds() from public, anon;
grant execute on function public.pack_seeds() to authenticated, service_role;

-- ======== from supabase/upgrade-decree.sql ========

-- Peakhill NHL Survivor: Commissioner's Decree. Run once in the Supabase SQL editor,
-- after admin.sql. Safe to re-run.
--
-- A decree is a one-week rule twist. The commissioner either imposes one (one option)
-- or puts two or three to a league vote. Everyone can see decrees and the running vote
-- counts; nobody can see who voted for what. Decrees have to be posted, and votes
-- cast, at least 24 hours before that week's lock, and there are 3 a season unless the
-- commissioner changes that in the Commissioner tab (see decree_limit()).

create table if not exists public.decrees (
  week int primary key references public.weeks(week),
  options text[] not null check (
    array_length(options, 1) between 1 and 3
    and options <@ array[
      'spotlight:PTS', 'spotlight:PM', 'spotlight:SV', 'spotlight:WIN', 'opposite:PTS', 'opposite:PM', 'opposite:SV', 'opposite:WIN', 'bounty', 'mercy', 'sudden_death', 'amnesty', 'ceasefire', 'free_for_all', 'pack_day'
    ]::text[]
  ),
  created_at timestamptz not null default now()
);

create table if not exists public.decree_votes (
  week int not null references public.decrees(week) on delete cascade,
  user_id uuid not null default auth.uid() references public.profiles(id) on delete cascade,
  choice int not null check (choice >= 0),
  created_at timestamptz not null default now(),
  primary key (week, user_id)
);

-- Still more than 24 hours before the week locks.
create or replace function public.decree_open(w int) returns boolean
  language sql stable security definer set search_path = public
  as $$ select exists (select 1 from weeks where week = w and lock_at > now() + interval '24 hours') $$;

-- How many decrees a season: meta.decree.perSeason in league_config (from the
-- Commissioner tab), or 3 if that hasn't been set or upgrade-settings.sql hasn't run.
create or replace function public.decree_limit() returns int
  language plpgsql stable security definer set search_path = public
  as $$
  begin
    return coalesce((select (value #>> '{decree,perSeason}')::int from league_config where key = 'meta'), 3);
  exception when undefined_table or undefined_column then
    return 3;
  end
  $$;

alter table public.decrees enable row level security;
drop policy if exists "decrees readable" on public.decrees;
drop policy if exists "decrees commissioner insert" on public.decrees;
drop policy if exists "decrees commissioner delete" on public.decrees;
create policy "decrees readable" on public.decrees for select to authenticated using (true);
create policy "decrees commissioner insert" on public.decrees for insert to authenticated
  with check (public.is_admin() and public.decree_open(week) and (select count(*) from public.decrees) < public.decree_limit());
create policy "decrees commissioner delete" on public.decrees for delete to authenticated
  using (public.is_admin() and public.decree_open(week));

alter table public.decree_votes enable row level security;
drop policy if exists "votes own" on public.decree_votes;
drop policy if exists "votes insert own" on public.decree_votes;
drop policy if exists "votes update own" on public.decree_votes;
drop policy if exists "votes delete own" on public.decree_votes;
create policy "votes own" on public.decree_votes for select to authenticated using (user_id = auth.uid());
create policy "votes insert own" on public.decree_votes for insert to authenticated
  with check (user_id = auth.uid() and public.decree_open(week)
    and exists (select 1 from public.decrees d where d.week = decree_votes.week
                and array_length(d.options, 1) > 1 and decree_votes.choice < array_length(d.options, 1)));
create policy "votes update own" on public.decree_votes for update to authenticated
  using (user_id = auth.uid() and public.decree_open(week))
  with check (user_id = auth.uid() and public.decree_open(week)
    and exists (select 1 from public.decrees d where d.week = decree_votes.week
                and array_length(d.options, 1) > 1 and decree_votes.choice < array_length(d.options, 1)));
create policy "votes delete own" on public.decree_votes for delete to authenticated
  using (user_id = auth.uid() and public.decree_open(week));

-- Vote counts per option. Counts only, never who voted.
create or replace function public.decree_tally()
  returns table (week int, choice int, votes int)
  language sql stable security definer set search_path = public
  as $$ select v.week, v.choice, count(*)::int from decree_votes v group by v.week, v.choice $$;
revoke execute on function public.decree_tally() from public, anon;
grant execute on function public.decree_tally() to authenticated, service_role;

-- ======== from supabase/upgrade-settings.sql ========

-- Peakhill NHL Survivor: league settings the commissioner edits from the Commissioner tab.
-- Run once in the Supabase SQL editor, after admin.sql. Safe to re-run.
--
-- Three rows, readable by every member (everyone's app needs them to score the league), written
-- only by commissioners:
--   'rules'        survival bars and card rules, each change taking effect from a week
--   'meta'         lives, drops, decree limits, the commissioner's name, an announcement
--   'adjustments'  public point and life corrections, each with a reason
--
-- The table is league_config. (It was once also called league_settings, but that name already
-- belongs to the one-row invite-code table from upgrade-dub-invite.sql, so this file used to
-- skip creating it and put its policies on the invite table instead. The cleanup below undoes that.)

create table if not exists public.league_config (
  key text primary key check (key in ('rules', 'meta', 'adjustments')),
  value jsonb not null,
  updated_at timestamptz not null default now()
);

alter table public.league_config enable row level security;
drop policy if exists "config readable" on public.league_config;
drop policy if exists "config commissioner insert" on public.league_config;
drop policy if exists "config commissioner update" on public.league_config;
drop policy if exists "config commissioner delete" on public.league_config;
create policy "config readable" on public.league_config for select to authenticated using (true);
create policy "config commissioner insert" on public.league_config for insert to authenticated with check (public.is_admin());
create policy "config commissioner update" on public.league_config for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "config commissioner delete" on public.league_config for delete to authenticated using (public.is_admin());
revoke all on public.league_config from anon;

-- Cleanup: the invite-code table takes no API policies (only its functions read it), so remove
-- the ones an earlier version of this file added to it by mistake. They let any member read the code.
do $$
begin
  if to_regclass('public.league_settings') is not null then
    drop policy if exists "settings readable" on public.league_settings;
    drop policy if exists "settings commissioner insert" on public.league_settings;
    drop policy if exists "settings commissioner update" on public.league_settings;
    drop policy if exists "settings commissioner delete" on public.league_settings;
  end if;
end
$$;

-- How many decrees a season: meta.decree.perSeason in league_config (from the
-- Commissioner tab), or 3 if that hasn't been set.
create or replace function public.decree_limit() returns int
  language plpgsql stable security definer set search_path = public
  as $$
  begin
    return coalesce((select (value #>> '{decree,perSeason}')::int from league_config where key = 'meta'), 3);
  exception when undefined_table or undefined_column then
    return 3;
  end
  $$;

-- The decree insert policy uses decree_limit() (upgrade-decree.sql sets it up the same way).
do $$
begin
  if to_regclass('public.decrees') is not null then
    drop policy if exists "decrees commissioner insert" on public.decrees;
    create policy "decrees commissioner insert" on public.decrees for insert to authenticated
      with check (public.is_admin() and public.decree_open(week) and (select count(*) from public.decrees) < public.decree_limit());
  end if;
end
$$;

-- Tell the API about the table straight away, so the Commissioner tab can save without waiting
-- for Supabase to notice ("Could not find the table ... in the schema cache").
notify pgrst, 'reload schema';

-- ======== from supabase/upgrade-commissioner-ops.sql ========

-- Peakhill NHL Survivor: commissioner office tooling.
-- Run in Supabase → SQL Editor after admin.sql. Safe to re-run.
--
-- Extends the Week check-in (packs / card plays as flags only), decree vote
-- turnout (who voted, never which option), and week row helpers for the
-- commissioner's office tools.

-- ---- Check-in: slot counts plus pack/play flags (never which players/cards) ----

create or replace function public.admin_checkin(w int)
  returns table (
    user_id uuid,
    slots int,
    backups int,
    last_saved timestamptz,
    pack_kept boolean,
    played boolean
  )
  language sql stable security definer set search_path = public
  as $$
    with members as (
      select p.id from profiles p where public.is_admin()
    ),
    pick as (
      select pk.user_id,
             (count(*) filter (where pk.slot <> 'FIGHT'))::int as slots,
             count(pk.alt_id)::int as backups,
             max(pk.updated_at) as last_saved
      from picks pk
      where pk.week = w and public.is_admin()
      group by pk.user_id
    ),
    packs as (
      select c.user_id
      from card_plays c
      where c.week = w and c.card = '_keep'
        and c.card_uid like 'pack:w' || w::text || ':%'
        and public.is_admin()
      group by c.user_id
    ),
    plays as (
      select c.user_id
      from card_plays c
      where c.week = w
        and c.card = any (array[
          'jinx', 'load', 'heist', 'blue_shell', 'burn_notice',
          'clown', 'nickname', 'sixth', 'copycat', 'leech',
          'switcheroo', 'garbage', 'embargo', 'scout', 'duel'
        ]::text[])
        and public.is_admin()
      group by c.user_id
    )
    select m.id,
           coalesce(p.slots, 0),
           coalesce(p.backups, 0),
           p.last_saved,
           exists (select 1 from packs k where k.user_id = m.id),
           exists (select 1 from plays y where y.user_id = m.id)
    from members m
    left join pick p on p.user_id = m.id
    order by m.id
  $$;

-- ---- Decree vote turnout: who has cast a ballot (never the choice) ----

create or replace function public.admin_vote_turnout(w int)
  returns table (user_id uuid)
  language sql stable security definer set search_path = public
  as $$
    select v.user_id
    from decree_votes v
    where v.week = w and public.is_admin()
  $$;

-- ---- Week rows for commissioner office tools ----

create or replace function public.admin_week_rows(w int)
  returns table (
    user_id uuid,
    slot text,
    player_id int,
    alt_id int,
    double_down boolean,
    auto boolean,
    updated_at timestamptz
  )
  language sql stable security definer set search_path = public
  as $$
    select pk.user_id, pk.slot, pk.player_id, pk.alt_id, pk.double_down, coalesce(pk.auto, false), pk.updated_at
    from picks pk
    where pk.week = w and public.is_admin()
  $$;

create or replace function public.admin_week_plays(w int)
  returns setof public.card_plays
  language sql stable security definer set search_path = public
  as $$
    select c.* from card_plays c where c.week = w and public.is_admin()
  $$;

-- Pack seeds for every member and week (same hmac as pack_seeds).
create or replace function public.admin_pack_seeds()
  returns table (user_id uuid, week int, seed text)
  language sql stable security definer set search_path = public, extensions
  as $$
    select p.id, w.week,
      encode(extensions.hmac(p.id::text || '|' || w.week::text, (select secret from league_secret where id), 'sha256'), 'hex')
    from profiles p cross join weeks w
    where public.is_admin()
  $$;

revoke execute on function public.admin_checkin(int) from public, anon;
revoke execute on function public.admin_vote_turnout(int) from public, anon;
revoke execute on function public.admin_week_rows(int) from public, anon;
revoke execute on function public.admin_week_plays(int) from public, anon;
revoke execute on function public.admin_pack_seeds() from public, anon;

grant execute on function public.admin_checkin(int) to authenticated;
grant execute on function public.admin_vote_turnout(int) to authenticated;
grant execute on function public.admin_week_rows(int) to authenticated;
grant execute on function public.admin_week_plays(int) to authenticated;
grant execute on function public.admin_pack_seeds() to authenticated;

-- ======== from supabase/harden.sql ========

-- Peakhill NHL Survivor: lock the API down. Run in the Supabase SQL editor after the
-- other files (and again after adding a new table or function). Safe to re-run.
--
-- The app's public key ships to every browser, so anyone can call the API with it.
-- This file makes sure that key on its own gets nothing, and that signed-in members
-- can only read what the app already shows them and can't fake the fields the
-- server should own.

-- ---- Members only ----
-- Signed out (the anon role), nothing in the league is readable: no names, account
-- ids, picks, cards or locks. Every policy and function is for signed-in members.
revoke all on all tables in schema public from anon;
revoke all on all sequences in schema public from anon;
revoke execute on all functions in schema public from public, anon;
alter default privileges in schema public revoke all on tables from anon;
alter default privileges in schema public revoke all on sequences from anon;
alter default privileges in schema public revoke execute on functions from public, anon;

grant execute on all functions in schema public to authenticated, service_role;

-- The invite code can't be tried over the API. Only sign-up checks it, and Supabase
-- rate-limits sign-ups, so it can't be guessed by brute force.
revoke execute on function public.check_invite(text) from authenticated;

-- ---- The server owns the timestamps ----
-- Join dates decide when your first card pack arrives, so they can't be backdated.
-- Save times are set by the server too. The SQL editor and the data job are exempt.
create or replace function public.stamp_profile() returns trigger
  language plpgsql set search_path = public
  as $$
  begin
    if current_user in ('anon', 'authenticated') then
      new.created_at := case when tg_op = 'INSERT' then now() else old.created_at end;
    end if;
    return new;
  end
  $$;
drop trigger if exists stamp_profile on public.profiles;
create trigger stamp_profile before insert or update on public.profiles
  for each row execute function public.stamp_profile();

create or replace function public.stamp_updated() returns trigger
  language plpgsql set search_path = public
  as $$
  begin
    if current_user in ('anon', 'authenticated') then new.updated_at := now(); end if;
    return new;
  end
  $$;
drop trigger if exists stamp_updated on public.picks;
create trigger stamp_updated before insert or update on public.picks
  for each row execute function public.stamp_updated();

create or replace function public.stamp_created() returns trigger
  language plpgsql set search_path = public
  as $$
  begin
    if current_user in ('anon', 'authenticated') then new.created_at := now(); end if;
    return new;
  end
  $$;
drop trigger if exists stamp_created on public.unburns;
create trigger stamp_created before insert on public.unburns
  for each row execute function public.stamp_created();
drop trigger if exists stamp_created on public.decree_votes;
create trigger stamp_created before insert or update on public.decree_votes
  for each row execute function public.stamp_created();

-- ---- Size limits ----
-- Everyone downloads every profile and card row, so one oversized or garbage value
-- slows the app down for the whole league. NOT VALID: checks new writes only.
alter table public.profiles drop constraint if exists profiles_fav_team_check;
alter table public.profiles add constraint profiles_fav_team_check
  check (fav_team is null or fav_team ~ '^[A-Z]{2,3}$') not valid;
-- No control, zero-width or right-to-left characters, which can disguise one name as another.
alter table public.profiles drop constraint if exists profiles_display_name_chars;
alter table public.profiles add constraint profiles_display_name_chars
  check (display_name !~ '[[:cntrl:]​-‏‪-‮⁠-⁩﻿]') not valid;

alter table public.card_plays drop constraint if exists card_plays_size_check;
alter table public.card_plays add constraint card_plays_size_check
  check (octet_length(params::text) <= 1000 and (card_uid is null or char_length(card_uid) <= 80)) not valid;

-- A real week needs a handful of card rows; 40 is plenty, and stops anyone flooding the table.
create or replace function public.card_plays_cap() returns trigger
  language plpgsql set search_path = public
  as $$
  begin
    if current_user in ('anon', 'authenticated')
      and (select count(*) from public.card_plays c where c.user_id = new.user_id and c.week = new.week) >= 40 then
      raise exception 'Too many card plays this week.';
    end if;
    return new;
  end
  $$;
drop trigger if exists card_plays_cap on public.card_plays;
create trigger card_plays_cap before insert on public.card_plays
  for each row execute function public.card_plays_cap();
